mapper.select:
WITH RECURSIVE MENU_TREE AS ( SELECT M.MENU_ID , M.MENU_NAME , M.MENU_NAME_ENG , M.MENU_NAME_LOC , M.MENU_DESC , M.MENU_TYPE , M.LINK_URL , M.PARENT_MENU_ID , M.MENU_LEVEL , M.SORT_NO , M.USING_YN , M.SYSTEM_TYPE , LPAD(M.SORT_NO::VARCHAR, 10, '0') || '/' || M.MENU_ID AS SORT_PATH FROM MENU M WHERE NULLIF(TRIM(M.PARENT_MENU_ID), '') IS NULL
AND M.USING_YN = #{using_yn}
AND M.SYSTEM_TYPE = #{system_type}
UNION ALL
SELECT C.MENU_ID , C.MENU_NAME , C.MENU_NAME_ENG , C.MENU_NAME_LOC , C.MENU_DESC , C.MENU_TYPE , C.LINK_URL , C.PARENT_MENU_ID , C.MENU_LEVEL , C.SORT_NO , C.USING_YN , C.SYSTEM_TYPE , P.SORT_PATH || '/' || LPAD(C.SORT_NO::VARCHAR, 10, '0') || '/' || C.MENU_ID FROM MENU C INNER JOIN MENU_TREE P ON C.PARENT_MENU_ID = P.MENU_ID
AND C.USING_YN = #{using_yn}
AND C.SYSTEM_TYPE = #{system_type}
) SELECT MENU_ID , MENU_NAME , MENU_NAME_ENG , MENU_NAME_LOC , MENU_DESC , MENU_TYPE , LINK_URL , PARENT_MENU_ID , MENU_LEVEL , SORT_NO , USING_YN , SYSTEM_TYPE FROM MENU_TREE ORDER BY SORT_PATH

SELECT COUNT(*)
  FROM MENU
 WHERE MENU_ID = #{menu_id}

mapper.update:
UPDATE MENU
   SET MENU_NAME     = #{menu_name}
     , MENU_NAME_ENG = NULLIF(#{menu_name_eng}, '')
     , MENU_NAME_LOC = NULLIF(#{menu_name_loc}, '')
     , MENU_DESC     = NULLIF(#{menu_desc}, '')
     , MENU_TYPE     = #{menu_type}
     , LINK_URL      = NULLIF(#{link_url}, '')
     , SORT_NO       = CAST(#{sort_no} AS INTEGER)
     , USING_YN      = #{using_yn}
     , SYSTEM_TYPE   = #{system_type}
     , UPDATE_DATE   = NOW()
     , UPDATE_BY     = #{update_by}
 WHERE MENU_ID = #{menu_id}
